  windowRange:s.windowRange??[Math.max(0,Math.floor((s.start-map.firstNote)/lab.CONFIG.winStepMs)),
    Math.min(windows.length,Math.max(1,Math.ceil((s.end-map.firstNote)/lab.CONFIG.winStepMs)))]})):cm.rawSegs;
