   modelRc:lab.modelScores('rc',f,extra,cm.cutDemandRef),modelLn:lab.modelScores('ln',f,extra,cm.cutDemandRef),
   ruleRc:lab.scoreRc({f,extras:extra,cutDemandRef:cm.cutDemandRef}),ruleLn:lab.scoreLn({f,extras:extra}),
